import random

REF = [1, 2, 3, 4, 1, 2, 5, 1, 2, 3, 4, 5]      # 经典教材序列，用于暴露 Belady 异常

def faults_fifo(ref, ways):
    frames, q, miss = [], [], 0
    for x in ref:
        if x in frames:
            continue
        miss += 1
        if len(frames) < ways:
            frames.append(x); q.append(x)
        else:
            old = q.pop(0)
            frames[frames.index(old)] = x
            q.append(x)
    return miss

def faults_lru(ref, ways):
    frames, last, miss = [], {}, 0
    for i, x in enumerate(ref):
        if x in frames:
            last[x] = i                     # LRU：命中也要更新使用时间
            continue
        miss += 1
        if len(frames) < ways:
            frames.append(x)
        else:
            victim = min(frames, key=lambda f: last[f])
            frames[frames.index(victim)] = x
        last[x] = i
    return miss

def faults_rand(ref, ways, seed=7):
    rng = random.Random(seed)               # 固定种子 -> 输出可复现
    frames, miss = [], 0
    for x in ref:
        if x in frames:
            continue
        miss += 1
        if len(frames) < ways:
            frames.append(x)
        else:
            frames[rng.randrange(ways)] = x
    return miss

def faults_opt(ref, ways):
    frames, miss = [], 0
    for i, x in enumerate(ref):
        if x in frames:
            continue
        miss += 1
        if len(frames) < ways:
            frames.append(x)
            continue
        # 淘汰"未来最久才会被用到"的那一个；再也不出现则最优先淘汰
        victim, farthest = None, -1
        for f in frames:
            try:
                nxt = ref.index(f, i)
            except ValueError:
                nxt = 10 ** 9
            if nxt > farthest:
                farthest, victim = nxt, f
        frames[frames.index(victim)] = x
    return miss

print("=== replacement policies on a fixed reference string ===")
print("  reference string:", REF)
print("  (associative ways play the role of page frames)\n")
print("  %-6s %8s %8s %10s %8s" % ("ways", "FIFO", "LRU", "random", "OPT"))
table = {}
for w in (3, 4):
    row = (faults_fifo(REF, w), faults_lru(REF, w), faults_rand(REF, w), faults_opt(REF, w))
    table[w] = row
    print("  %-6d %8d %8d %10d %8d" % (w, row[0], row[1], row[2], row[3]))

print()
print("=== Belady anomaly (FIFO only) ===")
print("  FIFO with 3 ways  -> %d misses" % table[3][0])
print("  FIFO with 4 ways  -> %d misses" % table[4][0])
print("  MORE capacity produced MORE misses: %s" % ("YES, anomaly reproduced"
      if table[4][0] > table[3][0] else "no"))
print("  LRU with 3 -> %d, with 4 -> %d  (never increases)" % (table[3][1], table[4][1]))
print("  OPT with 3 -> %d, with 4 -> %d  (the theoretical lower bound)"
      % (table[3][3], table[4][3]))

print()
print("why: LRU and OPT are STACK algorithms. The resident set with C ways is always a")
print("     subset of the resident set with C+1 ways, so hit rate can never drop.")
print("     FIFO does not have that property, so it can suffer the anomaly.")
print("     OPT is unimplementable (it needs the future) -- it only bounds the others.")
